class PhoneSyncWorker:
    def __init__(self, profiles, gateway):
        self._profiles = profiles
        self._gateway = gateway

    def run(self, customer_id):
        profile = self._profiles.get(customer_id)
        phone = profile.primary_phone()
        logger.info('syncing phone %s for customer %s' % (phone, customer_id))
        try:
