from fastapi import APIRouter, Response

router = APIRouter(prefix='/auth')


@router.post('/login')
def login(payload, users, sessions, response: Response):
    user = users.by_email(payload.email)
    if user is None or not users.verify(payload.password, user.password_hash):
        raise PermissionError('invalid credentials')
    session_id = sessions.open(user.id)
    response.set_cookie('sid', session_id, httponly=True, secure=True)
    return {'user_id': user.id, 'display_name': user.display_name}

